test('S-002 · Request an increase to my daily or per-transaction payment limit subject to risk checks meets latency budget', async ({ request }) => {
  const samples: number[] = [];
  for (let i = 0; i < 20; i++) {
    const t0 = Date.now();
    const res = await request.get('/request_an_increase_to_my_daily_or_per_transaction_payment_limit_subject_to_risk_checks');
    samples.push(Date.now() - t0);
    expect(res.ok()).toBeTruthy();
  }
  samples.sort((a, b) => a - b);
  const p95 = samples[Math.floor(samples.length * 0.95) - 1];
  expect(p95).toBeLessThan(2000);
});

